-- COMPaSS database schema. Apply in the Supabase SQL editor or with `supabase db push`.
create type public.app_role as enum ('resident', 'toc', 'officer');
create type public.incident_status as enum ('received', 'assigned', 'in_progress', 'resolved');
create type public.incident_source as enum ('app', 'call', 'walk-in');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role app_role not null default 'resident', full_name text, created_at timestamptz not null default now());
create table public.patrol_points (id uuid primary key default gen_random_uuid(), name text not null, lat double precision not null check(lat between -90 and 90), lng double precision not null check(lng between -180 and 180), status text not null default 'available' check(status in ('available','unavailable')), created_at timestamptz not null default now());
create table public.incidents (id uuid primary key default gen_random_uuid(), reporter_id uuid references public.profiles(id), source incident_source not null default 'app', type text not null check(type in ('theft','disturbance','accident','suspicious activity','other')), description text not null check(char_length(description) between 3 and 2000), carrying_note text, photo_url text, lat double precision not null check(lat between -90 and 90), lng double precision not null check(lng between -180 and 180), status incident_status not null default 'received', assigned_patrol_point_id uuid references public.patrol_points(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.risk_areas (id uuid primary key default gen_random_uuid(), name text, lat double precision not null, lng double precision not null, radius_m integer not null check(radius_m > 0), created_at timestamptz not null default now());
create table public.incident_events (id bigint generated always as identity primary key, incident_id uuid not null references public.incidents(id) on delete cascade, actor_id uuid references public.profiles(id), event_type text not null, details jsonb not null default '{}', created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.incidents enable row level security; alter table public.patrol_points enable row level security; alter table public.risk_areas enable row level security; alter table public.incident_events enable row level security;
create function public.is_toc() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='toc') $$;
create policy "own profile" on profiles for select using (id=auth.uid() or public.is_toc());
create policy "residents view own incidents" on incidents for select using (reporter_id=auth.uid() or public.is_toc());
create policy "resident creates own report" on incidents for insert with check (reporter_id=auth.uid() and source='app' and status='received' and assigned_patrol_point_id is null);
create policy "toc manages incidents" on incidents for all using (public.is_toc()) with check (public.is_toc());
create policy "all authenticated see patrol points" on patrol_points for select to authenticated using (true); create policy "toc manages patrol points" on patrol_points for all using (public.is_toc()) with check (public.is_toc());
create policy "toc manages risk areas" on risk_areas for all using (public.is_toc()) with check (public.is_toc());
create policy "events visible to owner or toc" on incident_events for select using (public.is_toc() or exists(select 1 from incidents where incidents.id=incident_events.incident_id and reporter_id=auth.uid()));
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,new.raw_user_meta_data->>'full_name','resident'); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create function public.audit_incident() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='INSERT' then insert into incident_events(incident_id,actor_id,event_type,details) values(new.id,auth.uid(),'created',jsonb_build_object('source',new.source)); elsif new.status is distinct from old.status then insert into incident_events(incident_id,actor_id,event_type,details) values(new.id,auth.uid(),'status_changed',jsonb_build_object('from',old.status,'to',new.status)); elsif new.assigned_patrol_point_id is distinct from old.assigned_patrol_point_id then insert into incident_events(incident_id,actor_id,event_type,details) values(new.id,auth.uid(),'assigned',jsonb_build_object('patrol_point_id',new.assigned_patrol_point_id)); end if; return new; end $$;
create function public.touch_incident() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger incidents_audit after insert or update on incidents for each row execute function public.audit_incident(); create trigger incidents_touch before update on incidents for each row execute function public.touch_incident();
alter publication supabase_realtime add table public.incidents;
